const $=id=>document.getElementById(id),element=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};let epoch=0,busy=false;
function clear(){epoch++;$('report').replaceChildren();$('incidents').replaceChildren();}
async function api(path,options={}){const token=sessionStorage.getItem('incident-session');if(!token)throw Error('请先登录');const response=await fetch('/api/incidents-v1'+path,{...options,headers:{Authorization:'Bearer '+token,...(options.body?{'Content-Type':'application/json'}:{}),...(options.key?{'Idempotency-Key':options.key}:{})}});const data=await response.json();if(!response.ok){if(response.status===401){sessionStorage.removeItem('incident-session');clear();}throw Error(data.error);}return data;}
async function guard(fn){try{await fn();}catch(e){$('status').textContent=e.message;}}
async function read(){const current=++epoch,project=$('project').value,id=$('report-id').value;$('report').replaceChildren();const data=await api(`/investigations/${encodeURIComponent(id)}?projectId=${encodeURIComponent(project)}`);if(current!==epoch)return;sessionStorage.setItem('investigation-last',JSON.stringify({project,id}));const root=$('report');root.append(element('h2',`草稿 ${data.reportId}`),element('p',`模式 ${data.mode} · 状态 ${data.executionState} · ${data.current?'证据快照仍匹配':'非当前有效草稿（失败、未结束或证据已变化）'} · 全部待复核`),element('p',`模型 ${data.modelVersion??'未调用'} · 版本 ${data.promptVersion}`),element('p',`证据摘要 ${data.evidenceManifestDigest??'未生成'}`));if(data.error)root.append(element('p','失败原因：'+data.error));for(const f of data.findings){const section=document.createElement('section');section.append(element('h3',`${f.type} · ${f.origin} · ${f.reviewStatus}`),element('p',f.statement));for(const [label,refs] of [['依据',f.evidenceRefs],['反证',f.counterEvidenceRefs]])for(const ref of refs){section.append(element('p',`${label} ${ref.id} [${ref.start},${ref.end})`),element('pre',ref.quote));}root.append(section);}root.append(element('h3','费用快照（确定性核算）'));for(const g of data.expenseSnapshot?.totals??[])root.append(element('p',`${g.currency}/${g.scale}位/${g.dataClass}：净额最小单位 ${g.netTotal??'未知'}；未知 ${g.unknownCount}`));root.append(element('p','缺项：'+(data.gaps??[]).join(', ')));for(const text of data.limitations??[])root.append(element('p',text));$('status').textContent='草稿已读取';}
$('load').onsubmit=e=>{e.preventDefault();guard(async()=>{clear();const current=epoch,project=$('project').value;let cursor='0';do{const page=await api(`/incidents?projectId=${encodeURIComponent(project)}&cursor=${cursor}`);if(current!==epoch)return;for(const incident of page.items){const b=element('button','生成规则草稿：'+incident.statement);let key=null;b.onclick=()=>guard(async()=>{if(busy)return;busy=true;b.disabled=true;key??=crypto.randomUUID();const generation=epoch;try{const result=await api(`/incidents/${incident.incidentId}/investigations`,{method:'POST',body:JSON.stringify({projectId:project}),key});if(generation===epoch){$('report-id').value=result.report.reportId;await read();}}finally{busy=false;b.disabled=false;}});$('incidents').append(b);}cursor=page.nextCursor;}while(cursor);$('status').textContent='事故已加载';});};
$('read').onsubmit=e=>{e.preventDefault();guard(read);};$('project').oninput=()=>{clear();sessionStorage.removeItem('investigation-last');};
$('logout').onclick=()=>guard(async()=>{try{await api('/session',{method:'DELETE'});}finally{sessionStorage.removeItem('incident-session');sessionStorage.removeItem('investigation-last');clear();$('report-id').value='';$('status').textContent='已退出';}});
$('project').value=sessionStorage.getItem('incident-project')||'';try{const saved=JSON.parse(sessionStorage.getItem('investigation-last')||'null');if(saved&&sessionStorage.getItem('incident-session')){$('project').value=saved.project;$('report-id').value=saved.id;guard(read);}}catch{sessionStorage.removeItem('investigation-last');}
